<?php
declare(strict_types=1);
require_once __DIR__.'/admin_actions.php';
require_once __DIR__.'/admin_presentation.php';
function cbAccountFields(string $role,array $a=[]): void {
    $fields=match($role){'student'=>['student_no'=>'Student number','username'=>'Username','first_name'=>'First name','last_name'=>'Last name','email'=>'Email (optional)','course'=>'Course','year_level'=>'Year level'],'professor'=>['employee_id'=>'Employee ID','username'=>'Username','full_name'=>'Full name','email'=>'Institutional email','department'=>'Department'],default=>['username'=>'Username','full_name'=>'Full name']};
    $creating=!isset($a['id']);
    if($creating){unset($fields['student_no'],$fields['employee_id']);$fields['username']='Username (optional)';}
    ?><div class="form-grid"><?php foreach($fields as $key=>$label){if($key==='department'){portalSelect($label,$key,[''=>'Choose department']+CB_DEPARTMENTS,$a[$key]??'','required');continue;}$optional=($key==='email'&&$role==='student')||($creating&&$key==='username');$readonly=in_array($key,['student_no','employee_id'],true)&&isset($a['public_id'])&&($a[$key]??'')===$a['public_id'];portalField($label,$key,$a[$key]??($key==='course'?'BS Information Technology':($key==='year_level'?'1st Year':($key==='department'?'College of Computer Studies':''))),$key==='email'?'email':'text',($optional?'':'required').($readonly?' readonly':''));}?></div><?php if($creating):?><p class="settings-help">Account ID is assigned automatically when you save: <?=h(match($role){'professor'=>'PROF','student'=>'STUD',default=>'ADMIN'})?>-<?=h(date('Y-m'))?>-00001. The final number advances for each new account. Leave username blank to use that ID for sign-in.</p><?php endif;
}
function cbPager(int $page,int $total,int $size=25): void {
    if(!$total)return;
    $pages=max(1,(int)ceil($total/$size));?><div class="record-pager"><span><?=$total?> <?=$total===1?'record':'records'?> · Page <?=$page?> of <?=$pages?></span><div><?php if($page>1):?><a href="?<?=h(http_build_query(array_merge($_GET,['page'=>$page-1])))?>">Previous</a><?php endif;if($page<$pages):?><a href="?<?=h(http_build_query(array_merge($_GET,['page'=>$page+1])))?>">Next</a><?php endif;?></div></div><?php
}
function cbAdminAccounts(PDO $db,array $u): void {
    cbAdminDirectoryStyles();
    $role=(string)($_GET['role']??'professor');if(!in_array($role,['professor','student','admin'],true))$role='professor';$table=cbAccountTable($role);
    $roleName=match($role){'professor'=>'Faculty','student'=>'Student',default=>'Administrator'};
    $q=trim(substr((string)($_GET['q']??''),0,100));$status=(string)($_GET['status']??'');$page=max(1,(int)($_GET['page']??1));$where='1=1';$args=[];
    if($q!==''){$field=$role==='student'?"CONCAT_WS(' ',a.student_no,a.first_name,a.last_name,a.email,m.public_id)":($role==='professor'?"CONCAT_WS(' ',a.employee_id,a.username,a.full_name,a.email,m.public_id)":"CONCAT_WS(' ',a.username,a.full_name,m.public_id)");$where.=" AND ($field COLLATE utf8mb4_unicode_ci) LIKE ?";$args[]='%'.$q.'%';}
    if(in_array($status,['pending','active','inactive'],true)){$where.=" AND COALESCE(x.status,'active')=?";$args[]=$status;}
    $from=" FROM $table a LEFT JOIN classbook_access x ON x.role=? AND x.account_id=a.id LEFT JOIN classbook_account_meta m ON m.role=? AND m.account_id=a.id WHERE $where";array_unshift($args,$role,$role);
    $total=(int)cbQuery($db,'SELECT COUNT(*)'.$from,$args)->fetchColumn();$page=min($page,max(1,(int)ceil($total/25)));$offset=($page-1)*25;
    $rows=cbQuery($db,"SELECT a.*,m.public_id,COALESCE(x.status,'active') AS access_status".$from." ORDER BY a.id DESC LIMIT 25 OFFSET $offset",$args)->fetchAll();
    if(!isset($_GET['create'])): ?><div class="directory-toolbar"><p class="directory-help"><?=h($roleName)?> accounts · <?=$total?> <?=$total===1?'record':'records'?></p><a class="button" href="?view=accounts&amp;role=<?=h($role)?>&amp;create=1"><?=portalIcon('user-plus')?>Add <?=h(strtolower($roleName))?></a></div><?php endif;?><nav class="account-tabs" aria-label="Account types"><?php foreach(['professor'=>'Faculty','student'=>'Students','admin'=>'Administrators'] as $key=>$label):?><a href="?view=accounts&amp;role=<?=h($key)?>" class="<?=$role===$key?'active':''?>" <?=$role===$key?'aria-current="page"':''?>><?=portalIcon($key==='student'?'graduation-cap':($key==='admin'?'shield-check':'users'))?><?=h($label)?></a><?php endforeach;?></nav>
    <?php if(isset($_GET['create'])): ?>
    <section class="admin-panel create-account-panel" id="create-account"><div class="panel-heading"><div><h2>Create <?=h(strtolower($roleName))?> account</h2><p>Use the school's verified details. Approve access and issue an activation code after creation.</p></div><a class="button secondary" href="?view=accounts&amp;role=<?=h($role)?>">Back to accounts</a></div><form method="post"><?php portalPost('create_account');?><input type="hidden" name="role" value="<?=$role?>"><?php cbAccountFields($role);?><div class="actions"><button><?=portalIcon('user-plus')?>Create pending account</button><a class="button secondary" href="?view=accounts&amp;role=<?=h($role)?>">Cancel</a></div></form></section>
    <?php return; endif; ?>
    <form method="get" class="admin-filters" data-auto-filter><input type="hidden" name="view" value="accounts"><input type="hidden" name="role" value="<?=h($role)?>"><?php portalField('Search name, school ID or email','q',$q,'search','placeholder="Search accounts…"');portalSelect('Access status','status',[''=>'All statuses','pending'=>'Pending approval','active'=>'Active','inactive'=>'Deactivated'],$status);?><noscript><button class="quiet"><?=portalIcon('search')?>Search</button></noscript></form><?php portalFilterSummary([$q!==''?'Search: '.$q:'',$status!==''?'Access: '.match($status){'pending'=>'Pending approval','active'=>'Active',default=>'Deactivated'}:''],'registrar.php?'.http_build_query(['view'=>'accounts','role'=>$role]));?>
    <section class="admin-panel records-panel"><div class="panel-heading"><div><h2><?=h($roleName)?> accounts <span class="count-tag"><?=$total?></span></h2><p>Verify each person's identity before approving access or issuing a code.</p></div></div>
    <?php if(!$rows):$any=(int)$db->query('SELECT COUNT(*) FROM '.$table)->fetchColumn();cbAdminEmpty('users',$any?'No matching accounts':'No '.strtolower($roleName).' accounts yet',$any?'Try a different name or access status.':'Create an account, verify the owner, then approve access and issue an activation code.',$any?'?view=accounts&role='.$role:'?view=accounts&role='.$role.'&create=1',$any?'Clear filters':'Create '.strtolower($roleName).' account');else:?>
    <div class="admin-table-scroll"><table><thead><tr><th scope="col">Account holder</th><th scope="col">Account ID</th><th scope="col">Access status</th><th scope="col">Actions</th></tr></thead><tbody>
    <?php foreach($rows as $a):$fullName=$a['full_name']??($a['last_name'].', '.$a['first_name']);?><tr><td><strong><?=h($fullName)?></strong><small class="cell-subtitle"><?=h($a['email']??$a['username'])?></small></td><td><strong><?=h($a['public_id']??'')?></strong><?php $schoolId=$role==='student'?$a['student_no']:($role==='professor'?$a['employee_id']:'');if($schoolId!==''&&$schoolId!==($a['public_id']??'')):?><small class="cell-subtitle">School ID: <?=h($schoolId)?></small><?php endif;?><small class="cell-subtitle"><?=h($a['course']??$a['department']??'Administrator')?></small></td><td><?=cbAdminStatus($a['access_status'])?></td><td><?php if($role==='admin'&&(int)$a['id']===(int)$u['id']):?><a class="account-settings-action" href="profile.php" aria-label="Open your account settings" title="Account settings"><?=portalIcon('settings')?></a><?php else:$manageContext=['role'=>$role,'account_id'=>(int)$a['id']];if($q!=='')$manageContext['q']=$q;if($status!=='')$manageContext['status']=$status;if($page>1)$manageContext['page']=$page;?><a class="manage-account-link directory-action" href="manage-account.php?<?=h(http_build_query($manageContext))?>" aria-label="<?=h('Manage account for '.$fullName)?>" title="Manage account"><?=portalIcon('settings')?></a><?php endif;?></td></tr><?php endforeach;?></tbody></table></div><?php cbPager($page,$total);endif;?></section>
    <?php
}
require_once __DIR__.'/subject_directory.php';
function cbAdminClasses(PDO $db,array $u): void {
    cbAdminDirectoryStyles();
    cbSubjectDirectory($db);
    if(trim((string)($_GET['subject']??''))!=='')return;
    $professors=[];foreach(cbQuery($db,"SELECT p.id,p.full_name,p.department FROM professors p LEFT JOIN classbook_access x ON x.role='professor' AND x.account_id=p.id WHERE COALESCE(x.status,'active')<>'inactive' ORDER BY p.full_name")->fetchAll() as $p)$professors[$p['id']]=$p['full_name'].($p['department']?' · '.$p['department']:'');
    $year=(int)date('Y');$schoolYear=((int)date('n')>=6?$year:$year-1).'-'.((int)date('n')>=6?$year+1:$year);
    ?><details class="card collapsible-card" style="margin-top:22px" <?=!$professors?'open':''?>><summary>Create a class and assign a professor</summary><form method="post" id="create-class"><?php portalPost('create_class');?><p class="muted" style="margin:0 0 16px">The professor sees this class right away with the standard GRC criteria and grade conversion already set up.</p><?php if(!$professors){portalNotice('Create a professor account first.');?></form></details><?php return;}?><div class="form-grid"><?php portalSelect('Professor','professor_id',[''=>'Choose professor']+$professors,'','required');foreach(['subject_code'=>'Subject code','subject_title'=>'Subject title','section'=>'Section'] as $key=>$label)portalField($label,$key,'','text','required');portalField('School year','school_year',$schoolYear,'text','required');portalField('Units','units',3,'number','min="1" max="12" required');portalSelect('Semester','semester',array_combine(['1st Semester','2nd Semester','Summer'],['1st Semester','2nd Semester','Summer']));?></div><button><?=portalIcon('book-open')?>Create and assign class</button></form></details><?php
}
function cbAdminClassDetails(PDO $db,array $u,int $id): void {
    $legacyClass=cbQuery($db,'SELECT * FROM subjects WHERE id=?',[$id])->fetch();
    if(!$legacyClass){portalNotice('Class not found.','danger');return;}
    cbLegacyPanel($db,$id);
    if(!cbQuery($db,'SELECT subject_id FROM classbook_settings WHERE subject_id=?',[$id])->fetchColumn()){
        ?><form method="post" class="card"><?php portalPost('initialize_legacy');?><input type="hidden" name="subject_id" value="<?=$id?>"><h2>Initialize individual class records</h2><p>Legacy totals above remain intact. They will not be converted into invented attendance or activities.</p><?php portalField('Reason / migration reference','reason','','text','required maxlength="500"');?><button>Initialize preserved class</button></form><?php return;
    }
    try{$s=cbClass($db,$id,$u);?><section class="card"><div class="masterlist-top" style="margin-bottom:16px"><div><span class="eyebrow">GRADE SHEET VERIFICATION</span><h2><?=h($s['subject_code'].' · '.$s['section'].' · '.$s['state'])?></h2><p class="muted">Review supporting evidence. Only the professor can change scores and criteria.</p></div><?=cbAdminStatus($s['state']??'draft')?></div><div class="actions" style="margin-bottom:20px"><a class="button secondary" href="report.php?subject_id=<?=$id?>"><?=portalIcon('file-text')?>Grade report</a><a class="button secondary" href="report.php?subject_id=<?=$id?>&amp;version=published"><?=portalIcon('history')?>Release history</a><a class="button secondary" href="report.php?subject_id=<?=$id?>&amp;type=attendance"><?=portalIcon('clipboard-check')?>Attendance report</a><?php if($s['state']==='draft'&&!$s['archived']):?><a class="button secondary" href="reassign-class.php?subject_id=<?=$id?>" aria-label="Reassign professor" title="Reassign professor"><?=portalIcon('users')?>Reassign professor</a><?php endif;?></div>
    <?php if($s['state']==='submitted'):?><div class="faculty-class-context" style="background:#f8fafc;margin-bottom:18px"><div><strong>Ready for student release</strong><p>Publishing creates an immutable grade snapshot visible in each enrolled student's portal.</p></div><form method="post" class="inline-action" data-confirm="Release these results to students?"><?php portalPost('release',$s);?><button><?=portalIcon('circle-check')?>Release complete grade sheet</button></form></div><?php endif;
    if(in_array($s['state'],['submitted','released'],true)):?><form method="post" style="padding-top:16px;border-top:1px solid var(--line);margin-bottom:16px"><?php portalPost('return',$s);portalField('Correction reason','reason','','text','required maxlength="500" placeholder="Explain why this grade sheet is being returned to draft"');?><button class="quiet">Return / reopen for correction</button></form><?php endif;
    if($s['state']!=='submitted'):?><details class="collapsible-card" style="margin-top:12px"><summary><?=$s['archived']?'Unarchive':'Archive'?> class</summary><form method="post"><?php portalPost($s['archived']?'unarchive_class':'archive_class',$s);portalField('Reason','reason','','text','required maxlength="500"');?><button class="quiet"><?=$s['archived']?'Unarchive':'Archive; retain history'?></button></form></details><?php endif;?></section><?php
    // Individual grades are reviewed through the student masterlist.
    }catch(Throwable $e){portalNotice(portalError($e),'danger');}
}
function cbLegacyPanel(PDO $db,int $id): void {
    $rows=cbQuery($db,'SELECT g.*,s.student_no,s.first_name,s.last_name FROM grades g JOIN enrollments e ON e.id=g.enrollment_id JOIN students s ON s.id=e.student_id WHERE e.subject_id=? ORDER BY s.last_name',[$id])->fetchAll();
    if(!$rows)return;
    ?><details class="card collapsible-card"><summary>Preserved legacy percentage records</summary><p>These are the original aggregate columns, displayed using their original fixed formula. They have no individual activity evidence and are not automatically published by the new workflow.</p><table><tr><th>Student</th><th>Midterm</th><th>Final</th><th>Course</th><th>Source columns</th></tr><?php foreach($rows as $old):$g=computeStudentGrades($old);?><tr><td><?=h($old['student_no'].' · '.$old['last_name'])?></td><td><?=portalGrade($g['midterm_grade'])?></td><td><?=portalGrade($g['final_grade'])?></td><td><?=portalGrade($g['course_grade'])?></td><td><details><summary>Original values</summary><?php foreach($old as $key=>$value)if(str_starts_with($key,'mid_')||str_starts_with($key,'fnl_')):?><p><?=h($key)?>: <?=h($value??'Unrecorded')?></p><?php endif;?></details></td></tr><?php endforeach;?></table></details><?php
}
function cbAdminAudit(PDO $db): void {
    cbAdminDirectoryStyles();
    $q=trim(substr((string)($_GET['q']??''),0,100));$page=max(1,(int)($_GET['page']??1));$where='';$args=[];if($q!==''){$where=' WHERE action LIKE ? OR actor_role LIKE ? OR subject_id=?';$args=['%'.str_replace(' ','_',$q).'%','%'.($q==='administrator'?'admin':$q).'%',ctype_digit($q)?(int)$q:0];}
    $total=(int)cbQuery($db,'SELECT COUNT(*) FROM classbook_audit'.$where,$args)->fetchColumn();$page=min($page,max(1,(int)ceil($total/25)));$offset=($page-1)*25;
    $rows=cbAdminAuditRows($db,$where,$args,25,$offset);
    ?><form method="get" class="admin-filters audit-filter" data-auto-filter><input type="hidden" name="view" value="audit"><?php portalField('Search action, role or class ID','q',$q,'search','placeholder="For example: signed in, administrator, or a class ID"');?><noscript><button class="quiet"><?=portalIcon('search')?>Search</button></noscript></form><?php portalFilterSummary([$q!==''?'Search: '.$q:''],'registrar.php?view=audit');?>
    <section class="admin-panel records-panel"><div class="panel-heading"><div><h2>Recorded activity <span class="count-tag"><?=$total?></span></h2><p>A record of account access and changes to academic records.</p></div><span class="read-only-label"><?=portalIcon('shield-check')?>Read only</span></div><?php if(!$rows):cbAdminEmpty('history','No activity to display',$q!==''?'Try another action, role or class ID.':'Recorded account and class actions will appear here.');else:?>
    <div class="admin-table-scroll"><table><thead><tr><th scope="col">Date &amp; time</th><th scope="col">Performed by</th><th scope="col">Action</th><th scope="col">Class reference</th><th scope="col">Record details</th></tr></thead><tbody><?php foreach($rows as $a):?><tr><td><?=h(date('d M Y',strtotime($a['created_at'])))?><small class="cell-subtitle"><?=h(date('g:i a',strtotime($a['created_at'])))?></small></td><td><strong><?=h($a['actor_name']?:portalRoleLabel($a['actor_role']).' #'.$a['actor_id'])?></strong><small class="cell-subtitle"><?=h(portalRoleLabel($a['actor_role']))?></small></td><td><?=h(cbAdminActionLabel($a['action']))?></td><td><?php if($a['subject_id']):?><a href="?view=classes&amp;subject_id=<?=(int)$a['subject_id']?>">Class #<?=(int)$a['subject_id']?></a><?php else:?>Account activity<?php endif;?></td><td><details class="audit-details"><summary>View details</summary><pre><?=h(json_encode(json_decode($a['detail_json'],true),JSON_PRETTY_PRINT|JSON_UNESCAPED_UNICODE)?:$a['detail_json'])?></pre></details></td></tr><?php endforeach;?></tbody></table></div><?php cbPager($page,$total);endif;?></section><?php
}
